import torch, torch.nn as nn

def attention(q, k, v, mask=None):              # q: (B,h,n,dk)  k,v: (B,h,m,dk)
    s = q @ k.transpose(-2, -1) / q.size(-1) ** 0.5   # scores (B,h,n,m)
    if mask is not None:
        s = s.masked_fill(~mask, float("-inf"))      # False = not allowed
    return s.softmax(-1) @ v                       # (B,h,n,dk)

class MultiHeadAttention(nn.Module):
    def __init__(self, d, h):
        super().__init__()
        self.h = h
        self.wq, self.wk, self.wv, self.wo = (nn.Linear(d, d) for _ in range(4))

    def forward(self, x, mem, mask=None):          # x: (B,n,d)  mem: (B,m,d)
        B, n, d = x.shape
        split = lambda t: t.view(B, -1, self.h, d // self.h).transpose(1, 2)
        a = attention(split(self.wq(x)), split(self.wk(mem)), split(self.wv(mem)), mask)
        return self.wo(a.transpose(1, 2).reshape(B, n, d))   # concat heads, then W^O

class FFN(nn.Module):
    def __init__(self, d, d_ff):
        super().__init__()
        self.net = nn.Sequential(nn.Linear(d, d_ff), nn.ReLU(), nn.Linear(d_ff, d))

    def forward(self, x):
        return self.net(x)

import torch, torch.nn as nn
d, n, V = 128, 16, 1000
class Block(nn.Module):
    def __init__(self, pre):
        super().__init__()
        self.pre, self.v = pre, nn.Linear(d, d)
        self.f1, self.f2 = nn.Linear(d, 4 * d), nn.Linear(4 * d, d)
        self.n1, self.n2 = nn.LayerNorm(d), nn.LayerNorm(d)
        for m in (self.v, self.f1, self.f2):
            nn.init.xavier_normal_(m.weight); nn.init.zeros_(m.bias)
    def att(self, x):  # uniform attention
        return self.v(x).mean(1, keepdim=True).expand_as(x)
    def ffn(self, x):
        return self.f2(torch.relu(self.f1(x)))
    def forward(self, x):
        if self.pre:
            x = x + self.att(self.n1(x)); return x + self.ffn(self.n2(x))
        x = self.n1(x + self.att(x))
        return self.n2(x + self.ffn(x))
def run(pre, L, seed):
    torch.manual_seed(seed)
    blocks = nn.ModuleList(Block(pre) for _ in range(L))
    fin, head = nn.LayerNorm(d), nn.Linear(d, V)
    tok, h = torch.randint(0, V, (32, n)), torch.randn(32, n, d)
    lengths = []
    for b in blocks:
        h = b(h); lengths.append(h.norm(dim=-1).mean().item())
    if pre: h = fin(h)
    nn.functional.cross_entropy(head(h).reshape(-1, V), tok.reshape(-1)).backward()
    return blocks[-1].f2.weight.grad.norm().item(), lengths
for L in (6, 12, 24, 48):
    g = [sum(run(pre, L, s)[0] for s in range(8)) / 8 for pre in (False, True)]
    print(f"L={L}: post-LN {g[0]:.3f}  pre-LN {g[1]:.3f}  ratio {g[0] / g[1]:.1f}")
for pre in (False, True):
    print("pre " if pre else "post", [round(v, 1) for v in run(pre, 12, 0)[1]])
